int bonAppetit ( int n, int k, vector < int > bill, int b){

    const int sum = accumulate ( bill.begin(), bill.end(), 0 );
    const int peter = sum - bill[k];
    if( peter / 2 == b ){
        return 0;

    }else{
        return b - peter/2;
    }
}


